'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),out=path.join(root,'outputs/retirement-20years-20261011');
const suffixes=['a','b','c'],audits=suffixes.map(s=>JSON.parse(fs.readFileSync(path.join(out,`retirement20-${s}-audit.json`)))),bases=suffixes.map(s=>JSON.parse(fs.readFileSync(path.join(root,`outputs/youth-20years-20261011/youth20-${s}-audit.json`)))),careers=suffixes.map(s=>JSON.parse(fs.readFileSync(path.join(out,`retirement20-${s}-checkpoint.json`))));
const latest=Math.min(...audits.map(a=>a.seasonStats.length));
const baselineCareers=suffixes.map(s=>JSON.parse(fs.readFileSync(path.join(root,`outputs/youth-20years-20261011/youth20-${s}-checkpoint.json`))));
const mean=a=>a.length?a.reduce((s,n)=>s+n,0)/a.length:null,sum=a=>a.reduce((s,n)=>s+n,0);
const labels={ENG:'England',ESP:'Spanien',GER:'Deutschland',ITA:'Italien',FRA:'Frankreich',POR:'Portugal',NED:'Niederlande',BEL:'Belgien',AUT:'Österreich',SUI:'Schweiz',TUR:'Türkei',GRE:'Griechenland'};
function rows(a,season,phase,country){return a.snapshots.filter(r=>!r.simulationOnly&&!r.managed&&(!country||r.country===country)&&(season===0?r.phase==='initial':r.season===season&&r.phase===phase));}
function sample(a,b,c,season,country){
 const opening=rows(a,season,'opening',country),closed=rows(a,season,'closed',country),played=rows(a,season,'before-retirement',country),base=rows(a,0,'initial',country),control=rows(b,season,'closed',country),annual=a.annual.find(x=>x.season===season),costs=annual.clubs.filter(r=>!country||r.country===country),n=costs.length;
 assert(n===closed.length&&n>0);
 const initial=new Set(a.initialIds),active=[...c.world.clubs.flatMap(c=>c.roster),...c.world.market.freePlayers];
 return{qualityPct:100*(mean(closed.map(r=>r.quality))/mean(base.map(r=>r.quality))-1),openingQualityPct:100*(mean(opening.map(r=>r.quality))/mean(base.map(r=>r.quality))-1),playingQualityPct:100*(mean(played.map(r=>r.quality))/mean(base.map(r=>r.quality))-1),startingPct:100*(mean(played.map(r=>r.startingQuality))/mean(base.map(r=>r.startingQuality))-1),controlQualityPct:100*(mean(control.map(r=>r.quality))/mean(base.map(r=>r.quality))-1),openingPlayers:mean(opening.map(r=>r.rosterSize)),closingPlayers:mean(closed.map(r=>r.rosterSize)),minOpening:Math.min(...opening.map(r=>r.rosterSize)),minClosing:Math.min(...closed.map(r=>r.rosterSize)),meanAge:mean(closed.map(r=>r.meanAge)),expenses:sum(costs.map(r=>r.expenses))/n,salaries:sum(costs.map(r=>r.salaries))/n,youthFunding:sum(costs.map(r=>r.youthFunding))/n,promotionFees:sum(costs.map(r=>r.promotionFees))/n,transferFees:sum(c.world.transfers.filter(t=>t.season===season&&costs.some(r=>r.clubId===t.buyerId)).map(t=>t.price||0))/n,income:sum(costs.map(r=>r.income))/n,balance:sum(costs.map(r=>r.balance))/n,generated:sum(costs.map(r=>r.generated)),promoted:sum(costs.map(r=>r.promoted)),retired:sum(costs.map(r=>r.retired)),initialRemaining:sum(costs.map(r=>r.initialRemaining)),youthRosterSharePct:100*sum(closed.map(r=>r.origins.youth))/sum(closed.map(r=>r.rosterSize)),initialRemainingAllClubs:annual.initialRemainingAllClubs,initialRemainingIncludingFree:annual.initialRemainingIncludingFree};
}
function series(country){return Array.from({length:latest},(_,i)=>{const season=i+1,samples=audits.map((a,j)=>sample(a,bases[j],careers[j],season,country));const values=Object.fromEntries(Object.keys(samples[0]).map(k=>[k,mean(samples.map(s=>s[k]))]));return{season,...values,qualityRange:[Math.min(...samples.map(s=>s.qualityPct)),Math.max(...samples.map(s=>s.qualityPct))],minOpening:Math.min(...samples.map(s=>s.minOpening)),minClosing:Math.min(...samples.map(s=>s.minClosing))};});}
const total=series(),countries=Object.keys(labels).map(country=>({country,label:labels[country],series:series(country)}));
const tierSeries=Array.from({length:latest+1},(_,season)=>({season,aRelativeToDPct:mean(audits.map(a=>{const all=rows(a,season,'closed');return 100*(mean(all.filter(r=>r.tier==='A').map(r=>r.quality))/mean(all.filter(r=>r.tier==='D').map(r=>r.quality))-1);})),controlARelativeToDPct:mean(bases.map(a=>{const all=rows(a,season,'closed');return 100*(mean(all.filter(r=>r.tier==='A').map(r=>r.quality))/mean(all.filter(r=>r.tier==='D').map(r=>r.quality))-1);}))}));
for(const r of total){
 r.youthMinutesSharePct=mean(audits.map(a=>{const s=a.seasonStats.find(s=>s.season===r.season);return 100*s.minutes.youth/s.allMinutes;}));
 r.controlYouthMinutesSharePct=mean(bases.map(a=>{const s=a.seasonStats.find(s=>s.season===r.season);return 100*s.minutes.youth/s.allMinutes;}));
 r.controlMeanAge=mean(bases.map(a=>mean(rows(a,r.season,'closed').map(r=>r.meanAge))));
 r.controlStartingPct=mean(bases.map(a=>100*(mean(rows(a,r.season,'closed').map(r=>r.startingQuality))/mean(rows(a,0,'initial').map(r=>r.startingQuality))-1)));
 r.controlOpeningPlayers=mean(bases.map(a=>mean(rows(a,r.season,'opening').map(r=>r.rosterSize))));
 r.controlClosingPlayers=mean(bases.map(a=>mean(rows(a,r.season,'closed').map(r=>r.rosterSize))));
 r.controlGenerated=mean(bases.map(a=>a.births.filter(b=>b.kind==='youth'&&b.firstSeason===r.season&&b.clubId!=='AUT-5'&&!b.pid.includes(':Y0:')).length));
 r.controlPromoted=mean(baselineCareers.map(c=>c.world.careerEvents.events.filter(e=>e.type==='youth-promotion'&&e.season===r.season&&e.clubId!=='AUT-5').length));
}
const validation=audits.map((a,i)=>{const c=careers[i],initial=new Set(a.initialIds),active=[...c.world.clubs.flatMap(c=>c.roster),...c.world.market.freePlayers],survivors=active.filter(p=>initial.has(p.pid)),overAge=active.filter(p=>p.age>=39),decisions=a.annual.flatMap(s=>s.decisions),retired=new Set(a.retirements.map(r=>r.pid));assert(retired.size===a.retirements.length,'duplicate retirement');assert(overAge.length===0,'active age39+ after close');assert(a.seasonStats.every(s=>s.fixtures===991));const retiredInitial=a.retirements.filter(r=>initial.has(r.pid));return{seed:a.seed,seasons:a.seasonStats.length,fixtures:sum(a.seasonStats.map(s=>s.fixtures)),validated:a.seasonStats.filter(s=>s.validated).map(s=>s.season),initialPlayers:initial.size,initialRetired:retiredInitial.length,initialActive:survivors.length,initialActiveAges:Object.fromEntries([...new Set(survivors.map(p=>p.age))].sort((a,b)=>a-b).map(age=>[age,survivors.filter(p=>p.age===age).length])),initialActiveKinds:Object.fromEntries(['start','youth','cup','free'].map(kind=>[kind,survivors.filter(p=>a.births.find(b=>b.pid===p.pid)?.kind===kind).length])),initialMissingWithoutRetirement:initial.size-retiredInitial.length-survivors.length,retirements:a.retirements.length,maximumActiveAge:Math.max(...active.map(p=>p.age)),midpointDecisionDays:[Math.min(...decisions.map(d=>d.decisionDay)),Math.max(...decisions.map(d=>d.decisionDay))],retirementAges:Object.fromEntries(Array.from({length:7},(_,i)=>i+33).map(age=>[age,{decisions:decisions.filter(d=>d.age===age).length,retired:decisions.filter(d=>d.age===age&&d.retire).length}]))};});
const summary={createdAt:new Date().toISOString(),complete:latest===20,latest,method:'3 matched seeds; unchanged native football and finances; age33=40% +10pp per year; midseason deterministic decisions; season-end exits; 95 AI league clubs per world; costs Credits/club; youth counts total per world; pool Y0 excluded from annual generation',total,countries,tierSeries,validation,totals:{fixtures:sum(validation.map(v=>v.fixtures)),generated:mean(audits.map(a=>sum(a.annual.slice(0,latest).map(s=>sum(s.clubs.map(c=>c.generated)))))),promoted:mean(audits.map(a=>sum(a.annual.slice(0,latest).map(s=>sum(s.clubs.map(c=>c.promoted)))))),expenses:sum(total.map(s=>s.expenses)),salaries:sum(total.map(s=>s.salaries)),youthFunding:sum(total.map(s=>s.youthFunding)),promotionFees:sum(total.map(s=>s.promotionFees)),transferFees:sum(total.map(s=>s.transferFees))}};
fs.writeFileSync(path.join(out,'summary.json'),JSON.stringify(summary,null,2));
console.log(JSON.stringify({complete:summary.complete,latest,final:total.at(-1),validation:validation.map(v=>({seed:v.seed,seasons:v.seasons,initialActive:v.initialActive,validated:v.validated})),totals:summary.totals},null,2));
